// Flatten whatever the IMAP node hands us into the envelope the CRM expects.
// Doing it here — rather than in the CRM — is what keeps the API transport
// agnostic: swap IMAP for a provider webhook later and only this node changes.

const out = [];

for (const item of $input.all()) {
  const m = item.json;

  // mailparser returns addresses as { value: [{ address, name }], text }.
  const addr = (field) => {
    if (!field) return { email: null, name: null };
    if (typeof field === 'string') {
      const match = /<([^>]+)>/.exec(field);
      return { email: (match ? match[1] : field).trim().toLowerCase(), name: null };
    }
    const first = Array.isArray(field.value) ? field.value[0] : null;
    if (first) {
      return {
        email: (first.address || '').trim().toLowerCase() || null,
        name: first.name || null,
      };
    }
    return { email: null, name: null };
  };

  // Headers arrive as a Map, a plain object, or not at all depending on the
  // node's format setting. Normalise to lowercase string values, because the
  // CRM's classifier reads them by name.
  const headers = {};
  const raw = m.headers || m.headerLines || {};
  const entries = raw instanceof Map ? [...raw.entries()] : Object.entries(raw);
  for (const [key, value] of entries) {
    if (value == null) continue;
    headers[String(key).toLowerCase()] = Array.isArray(value)
      ? value.join(' ')
      : typeof value === 'object'
        ? JSON.stringify(value)
        : String(value);
  }

  const from = addr(m.from);
  const to = addr(m.to);

  out.push({
    json: {
      message_id: m.messageId || headers['message-id'] || null,
      in_reply_to: m.inReplyTo || headers['in-reply-to'] || null,
      references: m.references || headers['references'] || [],
      from_email: from.email,
      from_name: from.name,
      to_email: to.email,
      subject: m.subject || null,
      text: m.textPlain || m.text || m.textHtml || null,
      headers,
      received_at: m.date || new Date().toISOString(),
    },
  });
}

return out;
